css:
:scope { width: min(100%, 647px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 22; font-family: var(--os-font-label); font-size: 118px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i2 { grid-column: 4 / span 17; grid-row: 8 / span 12; aspect-ratio: 470 / 96; }
.gx__i3 { grid-column: 1 / span 23; grid-row: 23 / span 11; font-family: var(--os-font-body); font-size: 24px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 23; grid-row: 34 / span 4; font-family: var(--os-font-body); font-size: 24px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 94px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 19px; }
  .gx__i4 { font-family: var(--os-font-body); font-size: 19px; }
}
